    if any(sorted(vector) != names for vector in cal_vectors):
        raise ValueError("Calibration recordings do not have the same required feature set")
    cal_scores = sorted(_distance(vector, parameters)[0] for vector in cal_vectors)
    return {
        "schema": PROFILE_SCHEMA,
        "extractor": EXTRACTOR,
        "scorer": SCORER,
        "required_modalities": list(MODALITIES),
        "features": parameters,
        "training_count": len(training),
        "alpha": float(alpha),
        "threshold": cal_scores[rank - 1],
        "calibration": {"count": len(calibration), "rank": rank, "sorted_scores": cal_scores},
    }


def _finite_number(value: Any, name: str, *, positive: bool = False) -> None:
    if type(value) not in (int, float) or not math.isfinite(value):
        raise ValueError(f"Profile {name} must be a finite number")
    if (positive and value <= 0) or (not positive and value < 0):
        raise ValueError(f"Profile {name} is out of range")


def validate_profile(profile: Any) -> dict[str, Any]:
    if not isinstance(profile, dict):
        raise ValueError("Profile must be a JSON object")
    if profile.get("schema") != PROFILE_SCHEMA or profile.get("extractor") != EXTRACTOR or profile.get("scorer") != SCORER:
        raise ValueError("Unsupported profile schema, feature extractor or scorer")
    if profile.get("required_modalities") != list(MODALITIES):
        raise ValueError("Profile must require pointer, click, and text evidence")
    parameters = profile.get("features")
    if not isinstance(parameters, dict) or not parameters:
        raise ValueError("Profile must contain learned feature parameters")
    for name, parameter in parameters.items():
        if not isinstance(name, str) or name.split(".", 1)[0] not in MODALITIES:
            raise ValueError("Unknown profile feature modality")
        if not isinstance(parameter, dict) or set(parameter) != {"center", "scale"}:
            raise ValueError(f"Invalid parameters for profile feature {name}")
        # Correlations and log ratios can be negative.
        if type(parameter["center"]) not in (int, float) or not math.isfinite(parameter["center"]):
            raise ValueError(f"Profile feature {name} center must be finite")
        _finite_number(parameter["scale"], f"feature {name} scale", positive=True)
    if {name.split(".", 1)[0] for name in parameters} != set(MODALITIES):
        raise ValueError("Profile must contain features for every required modality")
    _finite_number(profile.get("threshold"), "threshold")
    if type(profile.get("alpha")) not in (int, float) or not 0 < profile["alpha"] < 1:
        raise ValueError("Profile alpha must be between 0 and 1")
    calibration = profile.get("calibration")
    if not isinstance(calibration, dict):
        raise ValueError("Missing calibration provenance")
    count, rank, scores = calibration.get("count"), calibration.get("rank"), calibration.get("sorted_scores")
    if type(count) is not int or count < 1 or type(rank) is not int or not 1 <= rank <= count:
        raise ValueError("Invalid calibration size/rank")
    if not isinstance(scores, list) or len(scores) != count:
        raise ValueError("Calibration score count does not match provenance")
    for score in scores:
        _finite_number(score, "calibration score")
    if scores != sorted(scores) or profile["threshold"] != scores[rank - 1]:
        raise ValueError("Profile threshold does not match stored calibration quantile")
    if rank != math.ceil((count + 1) * (1 - profile["alpha"])):
        raise ValueError("Profile calibration rank does not match alpha")
    return profile


def score_recording(profile: dict[str, Any], recording: dict[str, Any]) -> dict[str, Any]:
    """Score without modifying the profile or using any evaluation labels."""
    validate_profile(profile)
    issues = evidence_issues(recording)
    features = extract_features(recording)
    missing = sorted(set(profile["features"]) - set(features))
    extra = sorted(set(features) - set(profile["features"]))
    if missing and not issues:
        issues.append(f"Missing required features: {', '.join(missing)}")
    if extra:
        raise ValueError("Profile feature set does not match the current extractor")
    if issues:
        return {
            "score": None,
            "threshold": profile["threshold"],
            "decision": "insufficient_evidence",
            "features_used": sorted(set(features) & set(profile["features"])),
            "reasons": issues,
        }
    score, modality_scores = _distance(features, profile["features"])
    return {
        "score": score,
        "threshold": profile["threshold"],
        "decision": "match" if score <= profile["threshold"] else "doubt",
        "features_used": sorted(features),
        "modality_scores": modality_scores,
    }


def save_profile(profile: dict[str, Any], path: str | Path) -> None:
    validate_profile(profile)
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(profile, ensure_ascii=False, indent=2, sort_keys=True, allow_nan=False) + "\n", encoding="utf-8")



